<?php
declare(strict_types=1);
namespace CB\Dictionary\Integration\Builders\Bricks;
defined( 'ABSPATH' ) || exit;
final class DynamicData { private const PREFIX='cb_dictionary_';private const GROUP='Core Blueprint Dictionary';private const FIELDS=['cb_dictionary_id'=>'entry_id','cb_dictionary_title'=>'title','cb_dictionary_url'=>'url','cb_dictionary_pronunciation'=>'pronunciation','cb_dictionary_abbreviation'=>'abbreviation','cb_dictionary_synonyms'=>'synonyms','cb_dictionary_source'=>'source','cb_dictionary_featured'=>'featured','cb_dictionary_categories'=>'categories','cb_dictionary_tags'=>'tags','cb_dictionary_letters'=>'letters']; public static function init():void{add_filter('bricks/dynamic_tags_list',[self::class,'register_tags']);add_filter('bricks/dynamic_data/render_tag',[self::class,'render_tag'],20,3);add_filter('bricks/dynamic_data/render_content',[self::class,'render_content'],20,3);add_filter('bricks/frontend/render_data',[self::class,'render_content'],20,2);} public static function register_tags(array $tags):array{foreach(self::labels() as $n=>$l){$tags[]=['name'=>'{'.$n.'}','label'=>$l,'group'=>self::GROUP];}return $tags;} public static function render_tag(mixed $tag,mixed $post=null,string $context='text'):mixed{unset($post,$context);if(!is_string($tag)){return $tag;}$n=trim($tag,'{}');return isset(self::FIELDS[$n])?self::value($n):$tag;} public static function render_content(mixed $content,mixed $post=null,string $context='text'):mixed{unset($post,$context);if(!is_string($content)||false===strpos($content,'{'.self::PREFIX)){return $content;}return preg_replace_callback('/\{(cb_dictionary_[a-z0-9_]+)\}/',static function(array $m):string{$n=(string)$m[1];return isset(self::FIELDS[$n])?self::value($n):(string)$m[0];},$content)??$content;} private static function value(string $n):string{$r=Context::record();$v=$r[self::FIELDS[$n]]??'';if(is_bool($v)){return $v?'1':'0';}return is_scalar($v)?(string)$v:'';} private static function labels():array{return ['cb_dictionary_id'=>__('Dictionary · Entry ID','core-blueprint-dictionary'),'cb_dictionary_title'=>__('Dictionary · Term','core-blueprint-dictionary'),'cb_dictionary_url'=>__('Dictionary · Entry URL','core-blueprint-dictionary'),'cb_dictionary_pronunciation'=>__('Dictionary · Pronunciation','core-blueprint-dictionary'),'cb_dictionary_abbreviation'=>__('Dictionary · Abbreviation','core-blueprint-dictionary'),'cb_dictionary_synonyms'=>__('Dictionary · Synonyms','core-blueprint-dictionary'),'cb_dictionary_source'=>__('Dictionary · Source','core-blueprint-dictionary'),'cb_dictionary_featured'=>__('Dictionary · Featured','core-blueprint-dictionary'),'cb_dictionary_categories'=>__('Dictionary · Categories','core-blueprint-dictionary'),'cb_dictionary_tags'=>__('Dictionary · Tags','core-blueprint-dictionary'),'cb_dictionary_letters'=>__('Dictionary · Letters','core-blueprint-dictionary')];} }
